-- À exécuter seulement sur une base de test, sous un compte autorisé. Tous les gestes sont annulés.
begin;
do $$
declare r jsonb; bad jsonb; before_seq bigint; refused boolean; stamp text:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
begin
  if auth.uid() is null or not public.is_allowed() then raise exception 'Compte de test autorisé nécessaire';end if;
  if exists(select 1 from public.recipes where owner_id=auth.uid() and id='proof-l1-r') then raise exception 'Fixture déjà présente';end if;
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','trash','operation_id','proof-l1-trash','base_cycle_id',null,'at',stamp,'seed',jsonb_build_object('id','proof-l1-r','original_title','Pain de test'))));
  assert r->'accepted'->0->>'operation_id'='proof-l1-trash','01 : commande accusée';
  assert r->'accepted'->0->>'seed_used'='true','02 : création directement retirée';
  select server_seq into before_seq from public.recipes where owner_id=auth.uid() and id='proof-l1-r';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','trash','operation_id','proof-l1-trash','base_cycle_id',null,'at',stamp)));
  assert r->'accepted'->0->>'operation_id'='proof-l1-trash','03 : réessai accusé';
  assert (select server_seq=before_seq from public.recipes where owner_id=auth.uid() and id='proof-l1-r'),'04 : réessai sans nouvelle écriture';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','trash','operation_id','proof-l1-trash','base_cycle_id',null,'at',stamp,'seed',jsonb_build_object('id','proof-l1-r','original_title','Pain de test'))));
  assert r->'accepted'->0->>'seed_used'='true','04 bis : réessai après accusé perdu confirme aussi le contenu couvert';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','restore','operation_id','proof-l1-trash','base_cycle_id',null,'at',stamp)));
  assert r->'rejected'->0->>'reason'='cycle','04 ter : même operation_id avec autre action refusé';
  r:=public.sync_push(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','data',jsonb_build_object('id','proof-l1-r','original_title','Ancienne copie'),'updated_at',clock_timestamp()+interval '1 minute')));
  assert jsonb_array_length(r->'accepted')=0,'05 : ancien client refusé';
  refused:=false;
  begin update public.recipes set data=data-'lifecycle_id'-'trashed_at' where owner_id=auth.uid() and id='proof-l1-r';exception when check_violation then refused:=true;end;
  assert refused,'06 : REST direct refusé';
  refused:=false;
  begin insert into public.recipe_versions(owner_id,id,data,updated_at) values(auth.uid(),'proof-l1-v','{"id":"proof-l1-v","recipe_id":"proof-l1-r"}',clock_timestamp());exception when check_violation then refused:=true;end;
  assert refused,'07 : enfant tardif refusé';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','restore','operation_id','proof-l1-restore','base_cycle_id','proof-l1-trash','at',stamp)));
  assert r->'accepted'->0->>'operation_id'='proof-l1-restore','08 : restauration explicite';
  assert (select data->>'lifecycle_id'='proof-l1-restore' and data->>'trashed_at' is null from public.recipes where owner_id=auth.uid() and id='proof-l1-r'),'09 : cycle conservé après restauration';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','recipe_id','proof-l1-r','expected_cycle_id',null,'data',jsonb_build_object('id','proof-l1-r'),'updated_at',clock_timestamp()+interval '1 minute')));
  assert r->'rejected'->0->>'reason'='cycle','10 : ancien résultat refusé après restauration';
  refused:=false;
  begin perform public.sync_purge('recipes','proof-l1-r');exception when check_violation then refused:=true;end;
  assert refused,'11 : purge individuelle refusée';
  for bad in select * from jsonb_array_elements('[{}, {"action":null}, {"action":42}, {"action":"trash","operation_id":42}, {"action":"trash","base_cycle_id":42}]') loop
    r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','operation_id','proof-l1-invalid','base_cycle_id','proof-l1-restore','at',stamp)||bad));
    assert r->'rejected'->0->>'reason'='cycle' and jsonb_array_length(r->'accepted')=0,'12 : commande mal formée refusée';
  end loop;
  for bad in select * from jsonb_array_elements('[{"lifecycle_id":"archive-token"},{"lifecycle_id":42,"trashed_at":null},{"lifecycle_id":"archive-token","trashed_at":42}]') loop
    r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-malformed','archive_import',true,'data',jsonb_build_object('id','proof-l1-malformed')||bad,'updated_at',clock_timestamp())));
    assert jsonb_array_length(r->'accepted')=0,'13 : instantané mal formé refusé';
  end loop;
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-restore','data',jsonb_build_object('id','proof-l1-r','original_title','Correction explicite'),'updated_at',clock_timestamp()+interval '1 second')));
  assert jsonb_array_length(r->'accepted')=1 and (select data->>'lifecycle_id'='proof-l1-restore' from public.recipes where owner_id=auth.uid() and id='proof-l1-r'),'20 : contenu courant permis sans perdre le jeton';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-archive','archive_import',true,'data',jsonb_build_object('id','proof-l1-archive','lifecycle_id','archive-trash','trashed_at',stamp),'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'21 : initialisation archive retirée';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipe_versions','id','proof-l1-archive-v','recipe_id','proof-l1-archive','expected_cycle_id','archive-trash','archive_import',true,'data',jsonb_build_object('id','proof-l1-archive-v','recipe_id','proof-l1-archive'),'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'22 : enfant initial d’archive retirée';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipe_versions','id','proof-l1-archive-v-late','recipe_id','proof-l1-archive','expected_cycle_id','archive-trash','data',jsonb_build_object('id','proof-l1-archive-v-late','recipe_id','proof-l1-archive'),'updated_at',clock_timestamp())));
  assert r->'rejected'->0->>'reason'='cycle','23 : enfant ordinaire refusé même avec bon jeton si parent retiré';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-archive','recipe_id','proof-l1-archive','expected_cycle_id',null,'archive_import',true,'data',jsonb_build_object('id','proof-l1-archive'),'updated_at',clock_timestamp()+interval '1 minute')));
  assert r->'rejected'->0->>'reason'='cycle','24 : ancienne archive ne restaure pas une recette existante';
  refused:=false;
  begin insert into public.recipes(owner_id,id,data,updated_at) values(auth.uid(),'proof-l1-rest','{"id":"proof-l1-rest","lifecycle_id":"invented","trashed_at":null}',clock_timestamp());exception when check_violation then refused:=true;end;
  assert refused,'25 : REST ne crée pas de jeton réservé';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','inventory','id','proof-l1-portion','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-restore','data',jsonb_build_object('id','proof-l1-portion','source_recipe_id','proof-l1-r','portions',2),'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'26 : portion créée sur recette active';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','trash','operation_id','proof-l1-trash-again','base_cycle_id','proof-l1-restore','at',stamp)));
  assert jsonb_array_length(r->'accepted')=1,'27 : nouveau retrait';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','inventory','id','proof-l1-portion','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-restore','historique',true,'data',jsonb_build_object('id','proof-l1-portion','source_recipe_id','proof-l1-r','portions',1),'updated_at',clock_timestamp()+interval '1 second')));
  assert jsonb_array_length(r->'accepted')=1,'28 : consommation historique permise après retrait';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','shopping_lists','id','proof-l1-list','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-trash-again','historique',true,'data',jsonb_build_object('id','proof-l1-list','items',jsonb_build_array(jsonb_build_object('recipe_id','proof-l1-r'))),'updated_at',clock_timestamp())));
  assert r->'rejected'->0->>'reason'='cycle','29 : historique ne permet pas de créer une nouvelle liste avec recette retirée';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','restore','operation_id','proof-l1-final','base_cycle_id','proof-l1-trash-again','at',stamp)));
  assert jsonb_array_length(r->'accepted')=1,'30 : seconde restauration explicite';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-b','archive_import',true,'data','{"id":"proof-l1-b","lifecycle_id":"cycle-b","trashed_at":null}'::jsonb,'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'31 : archive active avec jeton conservé';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','meals','id','proof-l1-multi','recipe_contexts','[{"recipe_id":"proof-l1-r","expected_cycle_id":"proof-l1-final"},{"recipe_id":"proof-l1-b","expected_cycle_id":"wrong"}]'::jsonb,'data','{"id":"proof-l1-multi","items":[{"recipe_id":"proof-l1-r"},{"recipe_id":"proof-l1-b"}]}'::jsonb,'updated_at',clock_timestamp())));
  assert r->'rejected'->0->>'reason'='cycle','32 : tous les cycles multi-recettes sont vérifiés';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','meals','id','proof-l1-multi','recipe_contexts','[{"recipe_id":"proof-l1-r","expected_cycle_id":"proof-l1-final"},{"recipe_id":"proof-l1-b","expected_cycle_id":"cycle-b"}]'::jsonb,'data','{"id":"proof-l1-multi","items":[{"recipe_id":"proof-l1-r"},{"recipe_id":"proof-l1-b"}]}'::jsonb,'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'33 : références multi-recettes courantes acceptées';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipe_versions','id','proof-l1-archive-v','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-final','data','{"id":"proof-l1-archive-v","recipe_id":"proof-l1-r"}'::jsonb,'updated_at',clock_timestamp()+interval '5 seconds')));
  assert r->'rejected'->0->>'reason'='cycle','34 : réattribution enfant ne contourne pas ancien parent retiré';
  for bad in select * from jsonb_array_elements('[{"id":"proof-l1-v-a","recipe_id":"proof-l1-r"},{"id":"proof-l1-v-b","recipe_id":"proof-l1-r"}]') loop
    r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipe_versions','id',bad->>'id','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-final','data',bad,'updated_at',clock_timestamp())));
    assert jsonb_array_length(r->'accepted')=1,'35 : version courante créée';
  end loop;
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','meals','id','proof-l1-meal','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-final','data','{"id":"proof-l1-meal","items":[{"recipe_id":"proof-l1-r","recipe_version_id":"proof-l1-v-a","portions":2}]}'::jsonb,'updated_at',clock_timestamp())));
  assert jsonb_array_length(r->'accepted')=1,'37 : repas historique préparé';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','recipes','id','proof-l1-r','op','lifecycle','recipe_id','proof-l1-r','action','trash','operation_id','proof-l1-final-trash','base_cycle_id','proof-l1-final','at',stamp)));
  assert jsonb_array_length(r->'accepted')=1,'38 : dernier retrait';
  r:=public.sync_push_v2(jsonb_build_array(jsonb_build_object('store','meals','id','proof-l1-meal','recipe_id','proof-l1-r','expected_cycle_id','proof-l1-final','historique',true,'data','{"id":"proof-l1-meal","items":[{"recipe_id":"proof-l1-r","recipe_version_id":"proof-l1-v-b","portions":2}]}'::jsonb,'updated_at',clock_timestamp()+interval '5 seconds')));
  assert r->'rejected'->0->>'reason'='cycle','39 : historique ne permet pas de remplacer une version après retrait';
  assert public.sync_purge_all()>0,'40 : effacement global explicite du compte reste permis';
  raise notice 'L1 SQL : 42 assertions réussies';
end $$;
rollback;
